+function decodeHtml(value = '') {
+  return value.replace(/&(#x?[0-9a-f]+|amp|quot|apos|lt|gt);/gi, (_, token) => {
+    if (token[0] === '#') {
+      const hex = token[1].toLowerCase() === 'x';
