:root { --ink:#1d2a24; --muted:#6e7972; --paper:#f3f0e8; --card:#fffdf8; --green:#1e6249; --sage:#dfe9e2; --line:#d9dbd3; --danger:#a23c34; font-family: Inter, ui-sans-serif, system-ui, -apple-system, sans-serif; color:var(--ink); background:var(--paper); }
* { box-sizing:border-box; }
body { margin:0; min-height:100vh; background:radial-gradient(circle at 78% 8%, #e4ebe1 0 12%, transparent 34%), var(--paper); }
